-- New client project only. Grant only operations already permitted by copied staff/admin RLS policies. No anonymous table grants, no function grants, no policy changes.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND NOT rowsecurity) THEN RAISE EXCEPTION 'All public tables must have RLS'; END IF; END $$;
